import { describe, expect, it } from "vitest";
import { verifyWebhook, WebhookVerificationError, type WebhookErrorReason } from "./webhook.js";

// Fixed vectors computed independently with
//   printf '%s.' "$T"; cat body | openssl dgst -sha256 -hmac "$SECRET"
// (legacy: openssl dgst -sha256 -hmac "$SECRET" body). Not generated by the code under test.
const SECRET = "whsec_test_secret";
const OTHER_SECRET = "whsec_other_secret";
const T = 1767323045;
const now = () => T;

const BODY1 =
  '{"event":"charge.paid","event_id":"d1b0c3a2-0000-4000-8000-000000000001","created_at":"2026-01-02T03:04:05Z","charge_id":"ch_123","status":"paid","amount":100000,"currency":"IDR","mode":"live"}';
const BODY2 =
  '{"event":"payout.failed","event_id":"d1b0c3a2-0000-4000-8000-000000000002","created_at":"2026-01-02T03:04:05Z","payout_id":"po_9","status":"failed","amount":40000,"currency":"IDR","mode":"sandbox","reason":"Rekening tidak valid — gagal ✓ 日本"}';

const B1_V2 = "2018c5555c6d3aba3f16464677fe2628fa66e5cf786fcbd31d5078c9d6a864dc";
const B1_LEGACY = "830202cbcc20bf66c1b459df8ee96d5ef164e4f43390807f446187b5c1511e14";
const B2_V2 = "87bfb14fd6261671132d2b078f40fc9ea4c67336aa73988b6a1b10019145b168";
const B1_V2_OTHER = "7c8fcaa519041e148e2234293fc512a63f9b3b3bbb6dc2105c18663851a49e22";
const B1_OLD300 = "060fac12a9ec992be04a2be745791a02e478477bc2e7cec6ca04b91aba002b1f"; // t=T-300
const B1_OLD301 = "9319089c36da45fc5ac85360df30e02a66d6f6af3b2723b4c7a4a69aac2fed40"; // t=T-301
const B1_FUT300 = "012b80fde0d53dec2fda184843acba55558a03eb2968fad97bd6f891b2ed3ed1"; // t=T+300
const B1_FUT301 = "43548ff997ef4d6f1982da040a5a03923cd7ef02a60b69135d00f3095c12256c"; // t=T+301
const NOT_JSON_SIG = "11cc8c1fd3d46b04aba00e94652bfafdf22a53504b570f4e0e47462e3b05654a"; // body "not json"
const ARRAY_SIG = "ce111e366acba8c7e5d2cbf2544eed1850defc0e565adbcc826f94d784506e74"; // body "[1]"

const V2 = "X-Waffle-Signature-V2";

async function reason(p: Promise<unknown>): Promise<WebhookErrorReason> {
  try {
    await p;
  } catch (e) {
    expect(e).toBeInstanceOf(WebhookVerificationError);
    return (e as WebhookVerificationError).reason;
  }
  throw new Error("expected rejection");
}

describe("verifyWebhook", () => {
  it("accepts a valid V2 delivery and returns the typed envelope", async () => {
    const ev = await verifyWebhook(
      BODY1,
      { [V2]: `t=${T},v1=${B1_V2}`, "X-Waffle-Delivery": "d1b0c3a2-0000-4000-8000-000000000001" },
      SECRET,
      { now },
    );
    expect(ev).toMatchObject({
      event: "charge.paid",
      eventId: "d1b0c3a2-0000-4000-8000-000000000001",
      createdAt: "2026-01-02T03:04:05Z",
      chargeId: "ch_123",
      payoutId: undefined,
      status: "paid",
      amount: 100000,
      currency: "IDR",
      mode: "live",
      deliveryId: "d1b0c3a2-0000-4000-8000-000000000001",
    });
    expect(ev.raw.charge_id).toBe("ch_123");
  });

  it("accepts Uint8Array and ArrayBuffer bodies and fetch Headers", async () => {
    const bytes = new TextEncoder().encode(BODY1);
    const h = new Headers({ [V2]: `t=${T},v1=${B1_V2}` });
    await verifyWebhook(bytes, h, SECRET, { now });
    await verifyWebhook(bytes.buffer.slice(0) as ArrayBuffer, h, SECRET, { now });
  });

  it("handles unicode bodies (UTF-8 bytes are signed)", async () => {
    const ev = await verifyWebhook(BODY2, { [V2]: `t=${T},v1=${B2_V2}` }, SECRET, { now });
    expect(ev.payoutId).toBe("po_9");
    expect(ev.raw.reason).toBe("Rekening tidak valid — gagal ✓ 日本");
  });

  const failures: [string, string, string, Record<string, string>, WebhookErrorReason, object?][] = [
    ["tampered body", BODY1 + " ", SECRET, { [V2]: `t=${T},v1=${B1_V2}` }, "signature_mismatch"],
    ["wrong secret", BODY1, OTHER_SECRET, { [V2]: `t=${T},v1=${B1_V2}` }, "signature_mismatch"],
    ["signed with other secret", BODY1, SECRET, { [V2]: `t=${T},v1=${B1_V2_OTHER}` }, "signature_mismatch"],
    ["timestamp altered", BODY1, SECRET, { [V2]: `t=${T + 1},v1=${B1_V2}` }, "signature_mismatch"],
    ["stale 301s", BODY1, SECRET, { [V2]: `t=${T - 301},v1=${B1_OLD301}` }, "timestamp_out_of_tolerance"],
    ["future 301s", BODY1, SECRET, { [V2]: `t=${T + 301},v1=${B1_FUT301}` }, "timestamp_out_of_tolerance"],
    ["custom tolerance", BODY1, SECRET, { [V2]: `t=${T - 301},v1=${B1_OLD301}` }, "timestamp_out_of_tolerance", { toleranceSeconds: 60 }],
    ["no headers", BODY1, SECRET, {}, "missing_signature"],
    ["legacy disallowed", BODY1, SECRET, { "X-Waffle-Signature": `sha256=${B1_LEGACY}` }, "missing_signature", { allowLegacy: false }],
    ["no v1", BODY1, SECRET, { [V2]: `t=${T}` }, "malformed_header"],
    ["no t", BODY1, SECRET, { [V2]: `v1=${B1_V2}` }, "malformed_header"],
    ["garbage", BODY1, SECRET, { [V2]: "garbage" }, "malformed_header"],
    ["empty", BODY1, SECRET, { [V2]: "" }, "malformed_header"],
    ["t not numeric", BODY1, SECRET, { [V2]: `t=abc,v1=${B1_V2}` }, "malformed_header"],
    ["duplicate t", BODY1, SECRET, { [V2]: `t=${T},t=${T},v1=${B1_V2}` }, "malformed_header"],
    ["v1 not hex", BODY1, SECRET, { [V2]: `t=${T},v1=zzzz` }, "malformed_header"],
    ["v1 short", BODY1, SECRET, { [V2]: `t=${T},v1=abcd` }, "malformed_header"],
    ["legacy without prefix", BODY1, SECRET, { "X-Waffle-Signature": B1_LEGACY }, "malformed_header"],
    ["invalid V2 never falls back to legacy", BODY1, SECRET, { [V2]: `t=${T},v1=${B1_V2_OTHER}`, "X-Waffle-Signature": `sha256=${B1_LEGACY}` }, "signature_mismatch"],
  ];
  it.each(failures)("rejects: %s", async (_n, body, secret, headers, want, opts) => {
    expect(await reason(verifyWebhook(body, headers, secret, { now, ...opts }))).toBe(want);
  });

  it("accepts exactly 300s old and 300s in the future (inclusive)", async () => {
    await verifyWebhook(BODY1, { [V2]: `t=${T - 300},v1=${B1_OLD300}` }, SECRET, { now });
    await verifyWebhook(BODY1, { [V2]: `t=${T + 300},v1=${B1_FUT300}` }, SECRET, { now });
  });

  it.each([
    ["lowercase header name", { "x-waffle-signature-v2": `t=${T},v1=${B1_V2}` }],
    ["uppercase header name", { "X-WAFFLE-SIGNATURE-V2": `t=${T},v1=${B1_V2}` }],
    ["extra whitespace", { [V2]: `  t=${T} ,  v1=${B1_V2}  ` }],
    ["unknown fields ignored", { [V2]: `t=${T},v0=deadbeef,v1=${B1_V2},v9=x` }],
    ["multiple v1 (second matches)", { [V2]: `t=${T},v1=${B1_V2_OTHER},v1=${B1_V2}` }],
    ["multiple v1 (first matches)", { [V2]: `t=${T},v1=${B1_V2},v1=${B1_V2_OTHER}` }],
    ["uppercase hex", { [V2]: `t=${T},v1=${B1_V2.toUpperCase()}` }],
  ])("accepts: %s", async (_n, headers) => {
    await verifyWebhook(BODY1, headers, SECRET, { now });
  });

  it("falls back to legacy only when V2 is absent (no replay protection)", async () => {
    const h = { "x-waffle-signature": `sha256=${B1_LEGACY}`, "X-Waffle-Delivery": "abc" };
    const ev = await verifyWebhook(BODY1, h, SECRET, { now: () => 1 });
    expect(ev.event).toBe("charge.paid");
    expect(ev.deliveryId).toBe("abc");
    expect(await reason(verifyWebhook(BODY1 + " ", h, SECRET))).toBe("signature_mismatch");
    expect(await reason(verifyWebhook(BODY1, h, OTHER_SECRET))).toBe("signature_mismatch");
  });

  it("reports invalid_json for validly signed non-object bodies", async () => {
    expect(await reason(verifyWebhook("not json", { [V2]: `t=${T},v1=${NOT_JSON_SIG}` }, SECRET, { now }))).toBe("invalid_json");
    expect(await reason(verifyWebhook("[1]", { [V2]: `t=${T},v1=${ARRAY_SIG}` }, SECRET, { now }))).toBe("invalid_json");
  });

  it("requires a secret and never leaks it or signatures in errors", async () => {
    await expect(verifyWebhook(BODY1, {}, "")).rejects.toBeInstanceOf(TypeError);
    const err = await verifyWebhook(BODY1, { [V2]: `t=${T},v1=${B1_V2_OTHER}` }, SECRET, { now }).catch((e: Error) => e);
    expect(String((err as Error).message)).not.toContain(SECRET);
    expect(String((err as Error).message)).not.toContain(B1_V2);
  });
});
